example.code:
// Tableau calculated fields

// Profit Ratio (aggregate calculation)
SUM([Profit]) / SUM([Sales])

// Order Size (row-level calculation)
IF [Sales] >= 500 THEN "Large"
ELSEIF [Sales] >= 100 THEN "Medium"
ELSE "Small"
END

// Sales month (for grouping)
DATETRUNC('month', [Order Date])

// Tableau LOD expressions

// First order date per customer (cohort)
{FIXED [Customer ID] : MIN([Order Date])}

// Cohort year, for colour or rows
YEAR({FIXED [Customer ID] : MIN([Order Date])})

// Average sales per customer, at the level of the view
AVG({INCLUDE [Customer ID] : SUM([Sales])})

// Measure switch driven by a string parameter [Choose measure]
CASE [Choose measure]
WHEN "Sales" THEN SUM([Sales])
WHEN "Profit" THEN SUM([Profit])
END

// Looker Studio calculated fields (data source level)

// Market group
CASE
  WHEN Country IN ("France", "Belgium", "Switzerland") THEN "Francophone Europe"
  WHEN Country = "Tunisia" THEN "North Africa"
  ELSE "Other"
END

// Average order value (metric)
SUM(Revenue) / COUNT_DISTINCT(Order_ID)

// Campaign is a brand campaign
REGEXP_MATCH(Campaign, ".*brand.*")

